const cfg = $('Config').first().json;
const page = $('Get General tools page').first().json;
const sheet = $('Get checklist sheet').first().json;

const WIDTH = 10;
const KEY = 8;
const NOTE = 9;
const HEADER_KEY = 'Sync key (General tools)';
const HEADER_NOTE = 'Sync note';
const NEW_PREFIX = 'New from General tools';
const ORPHAN_PREFIX = 'Not on General tools since';
const DUP_PREFIX = 'Duplicate sync key';
const today = $now.setZone('Europe/Zagreb').toFormat('yyyy-MM-dd');
const newNote = NEW_PREFIX + ' ' + today + ' - set Status, Priority and Owner';

// Confluence category -> existing checklist section (sheet sections are kept as they are)
const SECTION_MAP = {
  'communication & collaboration': 'Project Management',
  'project management': 'Project Management',
  'design&product': 'Design&Product',
  'engineering (dev, devops & qa)': 'Engineering (Dev, DevOps & QA)',
  'ai': 'Engineering (Dev, DevOps & QA)',
  'security': 'Security',
  'customer support': 'Customer Support',
  'payments': 'Payments',
  'marketing & advertising': 'Marketing & Others tools',
  'analytics & experimentation': 'Marketing & Others tools',
  'marketing & others tools': 'Marketing & Others tools',
  'hr': 'HHRR'
};

// One-time mapping for checklist rows whose name differs from General tools (approved 2026-09-24)
const ALIASES = {
  'slack grid': ['Slack workspace'],
  'microsoft (mail, calendar, onedrive)': ['Microsoft 365 (Mail, Calendar, OneDrive)'],
  'loom (video recorder)': ['Loom'],
  'fireflies.ai (confcalls ai summarizer)': ['Fireflies'],
  'zoom (confcalls)': ['Zoom'],
  'workboard (okrs - leadership team)': ['Workboard'],
  'flaticon or freepik (same company) - one time use tool': ['Flaticon', 'Freepik'],
  'untitledui (www.untitledui.com) - one time use tool (react components)': ['UntitledUI'],
  'okta (anual invocie, paid directly by transfer)': ["Okta (providing access to some tools + project's webpage access)"],
  'groundcover ($35usd per node under the plan we have now)': ['GroundCover'],
  'aircall': ['Aircall (IVR)'],
  'stripe access + rotate keys': ['Stripe']
};

function str(v) { return String(v === null || v === undefined ? '' : v).trim(); }
function norm(s) {
  return str(s).replace(/\u00a0/g, ' ').replace(/\(\s+/g, '(').replace(/\s+\)/g, ')').replace(/\s+/g, ' ').toLowerCase();
}
const INLINE = { paragraph: 1, heading: 1, text: 1 };
function nodeText(n) {
  if (!n) return '';
  if (n.type === 'text') return n.text || '';
  if (n.type === 'hardBreak') return ' ';
  if (n.type === 'inlineCard') return (n.attrs && n.attrs.url) || '';
  if (n.type === 'status' || n.type === 'mention' || n.type === 'emoji') return (n.attrs && (n.attrs.text || n.attrs.shortName)) || '';
  const parts = (n.content || []).map(nodeText);
  return INLINE[n.type] ? parts.join('') : parts.join(' ');
}
function findTable(n) {
  if (!n) return null;
  if (n.type === 'table') return n;
  for (const c of (n.content || [])) { const t = findTable(c); if (t) return t; }
  return null;
}

// ---- 1. Tools on the General tools page
const raw = page && page.body && page.body.atlas_doc_format && page.body.atlas_doc_format.value;
if (!raw) throw new Error('General tools page body (atlas_doc_format) is missing');
const adf = typeof raw === 'string' ? JSON.parse(raw) : raw;
const table = findTable(adf);
if (!table) throw new Error('No table found on the General tools page');
const conf = new Map();
let category = '';
let order = 0;
for (const row of (table.content || [])) {
  const cells = row.content || [];
  if (!cells.length || cells[0].type === 'tableHeader') continue;
  const first = nodeText(cells[0]).replace(/\s+/g, ' ').trim();
  if (!first) continue;
  const bg = String((cells[0].attrs && cells[0].attrs.background) || '').toLowerCase();
  const restEmpty = cells.slice(1).every(function (c) { return !nodeText(c).trim(); });
  if (bg === '#f4f5f7' || restEmpty) { category = first; continue; }
  const k = norm(first);
  if (!conf.has(k)) conf.set(k, { name: first, category: category, order: order++ });
}
if (conf.size < 30) throw new Error('Only ' + conf.size + ' tools parsed from General tools - aborting so the checklist is not touched');

// ---- 2. Rows in the checklist
const address = String(sheet.address || '');
const am = address.match(/!\$?([A-Z]+)\$?(\d+)/);
if (!am || am[1] !== 'A') throw new Error('Unexpected used range on the checklist: ' + address);
const startRow = parseInt(am[2], 10);
const values = (sheet.values || []).map(function (r) {
  const a = r.slice(0, WIDTH).map(function (v) { return v === null || v === undefined ? '' : v; });
  while (a.length < WIDTH) a.push('');
  return a;
});
if (!values.length || norm(values[0][0]) !== 'tool') throw new Error('Header row with "Tool" not found at A' + startRow);
const lastRow = startRow + values.length - 1;

const sections = [];
const toolRows = [];
let cur = null;
for (let i = 1; i < values.length; i++) {
  const r = values[i];
  const rowNum = startRow + i;
  const tool = str(r[0]);
  if (!tool) continue;
  const others = [1, 2, 3, 4, 5, 6, 7].map(function (j) { return str(r[j]); });
  const key = str(r[KEY]);
  const note = str(r[NOTE]);
  const nt = norm(tool);
  const bare = others.every(function (v) { return !v; }) && !key && !note;
  if (bare && !conf.has(nt) && !ALIASES[nt]) {
    cur = { name: tool, headerRow: rowNum, lastRow: rowNum };
    sections.push(cur);
    continue;
  }
  let keys = key ? key.split('|').map(function (s) { return s.trim(); }).filter(Boolean) : [];
  let adopted = false;
  if (!keys.length) {
    if (ALIASES[nt]) { keys = ALIASES[nt].slice(); adopted = true; }
    else if (conf.has(nt)) { keys = [conf.get(nt).name]; adopted = true; }
  }
  const curated = [r[1], r[3], r[4]].some(function (v) { return str(v) !== ''; });
  toolRows.push({ rowNum: rowNum, tool: tool, keys: keys, adopted: adopted, curated: curated, note: note, section: cur ? cur.name : '' });
  if (cur) cur.lastRow = rowNum;
}

// ---- 3. Coverage and duplicates
const covered = new Map();
for (const t of toolRows) {
  for (const k of t.keys) {
    const nk = norm(k);
    if (!conf.has(nk)) continue;
    if (!covered.has(nk)) covered.set(nk, []);
    if (covered.get(nk).indexOf(t) < 0) covered.get(nk).push(t);
  }
}
const report = { adopted: 0, added: [], orphaned: [], removed: [], back: [], duplicates: [], newSections: [], renames: [] };
for (const [nk, rows] of covered) {
  if (rows.length < 2) continue;
  const keep = rows.find(function (t) { return t.curated; }) || rows[0];
  for (const t of rows) {
    if (t === keep || t.deleteMe) continue;
    if (!t.curated && t.keys.length === 1) { t.deleteMe = true; report.removed.push(t.tool + ' (duplicate)'); }
    else if (!t.note.startsWith(DUP_PREFIX)) { t.dupOf = keep.rowNum; }
    else { t.dupOf = keep.rowNum; t.dupKnown = true; }
  }
}

// ---- 4. Desired sync key / note per row
const deletes = [];
for (const t of toolRows) {
  if (t.deleteMe) { deletes.push(t); continue; }
  const present = t.keys.some(function (k) { return conf.has(norm(k)); });
  let desired;
  if (t.dupOf) {
    desired = t.dupKnown ? t.note : DUP_PREFIX + ' - same tool as row ' + t.dupOf + ', please check';
    if (!t.dupKnown) report.duplicates.push(t.tool);
  } else if (!present) {
    if (!t.curated && t.keys.length) { t.deleteMe = true; deletes.push(t); report.removed.push(t.tool); continue; }
    if (t.note.startsWith(ORPHAN_PREFIX)) desired = t.note;
    else { desired = ORPHAN_PREFIX + ' ' + today; report.orphaned.push(t.tool); }
  } else if (!t.curated) {
    desired = t.note.startsWith(NEW_PREFIX) ? t.note : newNote;
  } else {
    desired = '';
    if (t.note.startsWith(ORPHAN_PREFIX)) report.back.push(t.tool);
  }
  t.desiredNote = desired;
  t.desiredKey = t.keys.join(' | ');
  if (t.adopted) report.adopted++;
}

// ---- 5. Tools missing from the checklist
const missing = Array.from(conf.entries())
  .filter(function (e) { return !covered.has(e[0]); })
  .map(function (e) { return e[1]; })
  .sort(function (a, b) { return a.order - b.order; });
const groups = new Map();
for (const t of missing) {
  const target = SECTION_MAP[norm(t.category)] || t.category || 'Other';
  if (!groups.has(target)) groups.set(target, []);
  groups.get(target).push(t);
}

// ---- 6. Build Graph requests (column I:J first, then structural edits bottom-up)
const base = 'https://graph.microsoft.com/v1.0/drives/' + cfg.driveId + '/items/' + cfg.itemId +
  "/workbook/worksheets('" + encodeURIComponent(cfg.sheetName) + "')";
const requests = [];

const byRow = new Map(toolRows.map(function (t) { return [t.rowNum, t]; }));
const ij = [];
let ijChanged = false;
for (let i = 0; i < values.length; i++) {
  const rowNum = startRow + i;
  const r = values[i];
  let k = str(r[KEY]);
  let n = str(r[NOTE]);
  if (i === 0) { k = HEADER_KEY; n = HEADER_NOTE; }
  else if (byRow.has(rowNum)) {
    const t = byRow.get(rowNum);
    if (!t.deleteMe && t.desiredNote !== undefined) { k = t.desiredKey; n = t.desiredNote; }
  }
  if (k !== str(r[KEY]) || n !== str(r[NOTE])) ijChanged = true;
  ij.push([k, n]);
}
if (ijChanged) {
  requests.push({ label: 'Update sync key/note columns', method: 'PATCH',
    url: base + "/range(address='I" + startRow + ':J' + lastRow + "')", body: { values: ij } });
}

function rowValues(t) { return [t.name, '', '', '', '', '', '', '', t.name, newNote]; }
const ops = [];
let appendAt = lastRow + 1;
for (const [target, tools] of groups) {
  const sec = sections.find(function (s) { return norm(s.name) === norm(target); });
  tools.forEach(function (t) { report.added.push(t.name + ' (' + target + ')'); });
  if (sec) {
    ops.push({ kind: 'insert', row: sec.lastRow + 1, values: tools.map(rowValues), section: target });
  } else {
    const vals = [[target, '', '', '', '', '', '', '', '', '']].concat(tools.map(rowValues));
    requests.push({ label: 'Append new section ' + target, method: 'PATCH',
      url: base + "/range(address='A" + appendAt + ':J' + (appendAt + vals.length - 1) + "')", body: { values: vals } });
    appendAt += vals.length;
    report.newSections.push(target);
  }
}
for (const t of deletes) ops.push({ kind: 'delete', row: t.rowNum });
ops.sort(function (a, b) { return (b.row - a.row) || (a.kind === 'delete' ? -1 : 1); });
for (const op of ops) {
  if (op.kind === 'delete') {
    requests.push({ label: 'Delete row ' + op.row, method: 'POST',
      url: base + "/range(address='" + op.row + ':' + op.row + "')/delete", body: { shift: 'Up' } });
  } else {
    const end = op.row + op.values.length - 1;
    requests.push({ label: 'Insert ' + op.values.length + ' row(s) in ' + op.section, method: 'POST',
      url: base + "/range(address='" + op.row + ':' + end + "')/insert", body: { shift: 'Down' } });
    requests.push({ label: 'Fill new row(s) in ' + op.section, method: 'PATCH',
      url: base + "/range(address='A" + op.row + ':J' + end + "')", body: { values: op.values } });
  }
}

// ---- 7. Possible renames (a tool that just left the page and a tool that just arrived look alike)
function words(s) { return norm(s).replace(/[^a-z0-9]+/g, ' ').split(' ').filter(function (w) { return w.length > 2; }); }
for (const o of report.orphaned) {
  const ow = words(o);
  let best = null;
  let bestScore = 0;
  for (const t of missing) {
    const tw = words(t.name);
    const inter = ow.filter(function (w) { return tw.indexOf(w) >= 0; }).length;
    const uni = new Set(ow.concat(tw)).size || 1;
    const score = inter / uni;
    if (score > bestScore) { bestScore = score; best = t.name; }
  }
  if (best && bestScore >= 0.34) report.renames.push('"' + o + '" -> "' + best + '"');
}

// ---- 8. Slack summary
function list(a) { return a.length > 25 ? a.slice(0, 25).join(', ') + ' and ' + (a.length - 25) + ' more' : a.join(', '); }
const lines = ['*General tools -> Delivery checklist sync*' + (cfg.isTest ? ' _(test copy)_' : '')];
if (report.adopted) lines.push('- Linked ' + report.adopted + ' existing checklist rows to General tools');
if (report.added.length) lines.push('- Added ' + report.added.length + ' tool(s): ' + list(report.added));
if (report.orphaned.length) lines.push('- No longer on General tools (kept, flagged in "Sync note"): ' + list(report.orphaned));
if (report.back.length) lines.push('- Back on General tools (flag cleared): ' + list(report.back));
if (report.removed.length) lines.push('- Removed (had no Status, Priority or Owner): ' + list(report.removed));
if (report.duplicates.length) lines.push('- Possible duplicates, please check: ' + list(report.duplicates));
if (report.newSections.length) lines.push('- New section(s) created at the bottom: ' + list(report.newSections));
if (report.renames.length) lines.push('- Possible renames, please check: ' + list(report.renames));
lines.push('<' + cfg.sheetUrl + '|Open the checklist>  |  <' + cfg.pageUrl + '|General tools page>');

return [{ json: {
  hasChanges: requests.length > 0,
  requestCount: requests.length,
  requests: requests,
  report: report,
  slackText: lines.join('\n'),
  stats: { toolsOnPage: conf.size, checklistRows: toolRows.length, sections: sections.map(function (s) { return s.name; }), usedRange: address }
} }];

const sessionId = $('Create workbook session').first().json.id;
const requests = $('Plan sync').first().json.requests || [];
return requests.map(function (r, i) { return { json: { seq: i + 1, label: r.label, method: r.method, url: r.url, body: r.body, sessionId: sessionId } }; });
